This is a miscompilation bug in ScalarEvolution.
Issue title: [IndVarSimplify] Miscompilation at O2
Detailed information:
BUG TYPE:
    miscompilation

VERIFICATION RESULT:
    Invalid refinement in @test -- Value mismatch

VIOLATED PROPERTY:
    return-value equality

SOURCE (pre-transformation IR):
define i32 @test() {
entry:
  br label %for.preheader

for.preheader:                                    ; preds = %for.inc, %entry
  %indvar1 = phi i32 [ 0, %entry ], [ %phi, %for.inc ]
  %indvar2 = phi i32 [ 1, %entry ], [ %indvar3, %for.inc ]
  %indvar3 = phi i32 [ 0, %entry ], [ %inc, %for.inc ]
  %cond1 = icmp eq i32 %indvar3, 0
  br i1 %cond1, label %for.inc, label %for.end

for.end:                                          ; preds = %for.preheader
  %cmp = icmp sgt i32 %indvar2, 0
  %ext = zext i1 %cmp to i32
  br label %for.inc

for.inc:                                          ; preds = %for.end, %for.preheader
  %phi = phi i32 [ %ext, %for.end ], [ 0, %for.preheader ]
  %inc = add i32 %indvar3, 1
  %exitcond = icmp eq i32 %indvar3, 2
  br i1 %exitcond, label %for.exit, label %for.preheader

for.exit:                                         ; preds = %for.inc
  ret i32 %indvar1
}

TARGET (post-transformation IR):
; ModuleID = '<stdin>'
source_filename = "<stdin>"

define i32 @test() {
entry:
  br label %for.preheader

for.preheader:                                    ; preds = %for.inc, %entry
  %indvar1 = phi i32 [ 0, %entry ], [ %phi, %for.inc ]
  %indvar3 = phi i32 [ 0, %entry ], [ %inc, %for.inc ]
  %cond1 = icmp eq i32 %indvar3, 0
  br i1 %cond1, label %for.inc, label %for.end

for.end:                                          ; preds = %for.preheader
  %ext = zext i1 true to i32
  br label %for.inc

for.inc:                                          ; preds = %for.end, %for.preheader
  %phi = phi i32 [ %ext, %for.end ], [ 0, %for.preheader ]
  %inc = add nuw nsw i32 %indvar3, 1
  %exitcond = icmp eq i32 %indvar3, 2
  br i1 %exitcond, label %for.exit, label %for.preheader

for.exit:                                         ; preds = %for.inc
  %indvar1.lcssa = phi i32 [ %indvar1, %for.inc ]
  ret i32 %indvar1.lcssa
}

WHAT THE TRANSFORMATION CHANGED:
  modified:
    %ext
      source: %ext = zext i1 %cmp to i32
      target: %ext = zext i1 true to i32
    %inc
      source: %inc = add i32 %indvar3, 1
      target: %inc = add nuw nsw i32 %indvar3, 1
  only in target:
    %indvar1.lcssa: %indvar1.lcssa = phi i32 [ %indvar1, %for.inc ]
  only in source:
    %indvar2: %indvar2 = phi i32 [ 1, %entry ], [ %indvar3, %for.inc ]
    %cmp: %cmp = icmp sgt i32 %indvar2, 0

CRITICAL VALUES:
    %indvar1.lcssa
    %indvar2

DEPENDENCY CHAIN (source):
    %indvar2 = phi i32 [ 1, %entry ], [ %indvar3, %for.inc ]
    %indvar3 = phi i32 [ 0, %entry ], [ %inc, %for.inc ]
    %inc = add i32 %indvar3, 1
    %exitcond = icmp eq i32 %indvar3, 2

CONTROL FLOW (blocks entered by the failing execution):
    %for.inc
    %for.exit

COUNTEREXAMPLE INPUT:
    (none)

DIVERGENCE (source vs target on that input):
    %indvar1.lcssa: source = (not computed)   target = #x00000001 (1)

INTERPRETATION:
    A transformation must preserve the returned value for every input on which the source is well-defined.
    On the input above the source yields #x00000000 (0) while the target yields #x00000001 (1).
    The earliest reported divergence is at %indvar1.lcssa.
    The target attaches 'nsw', 'nuw' to %inc, which the source does not. If that guarantee is not implied by the source, attaching it is unsound on its own.

